const $=s=>document.querySelector(s), STORE='petmaster.v1';
const nav=[['home','⌂','Home'],['practice','◎','Practice'],['papers','▤','PYQ Papers'],['mock','◷','Mock Tests'],['revision','↻','Revision'],['analytics','▥','Analytics'],['planner','▦','Study Planner'],['bank','▧','Question Bank'],['settings','⚙','Settings']];
const defaultConfig={totalQuestions:100,durationMinutes:120,marksCorrect:1,negativeMarks:.25,marksUnattempted:0};
let db={schemaVersion:1,config:defaultConfig,questions:[],attempts:[],active:null,bookmarks:[],notes:{},revision:{},mistakes:{},flashcards:[],planner:[],settings:{theme:'light',language:'hinglish'},lastPage:'home'};let page='home',timer=null,modalCallback=null,practiceFeedback=false,bankFilters={};
const clone=x=>JSON.parse(JSON.stringify(x));
function load(){try{const s=localStorage.getItem(STORE);if(s){const parsed=JSON.parse(s);db={...db,...parsed,config:{...defaultConfig,...parsed.config},settings:{...db.settings,...parsed.settings}}}}catch(e){toast('Could not read saved data. Export/backup may help.')} }
function save(){try{localStorage.setItem(STORE,JSON.stringify(db));return true}catch(e){toast('Storage is full or unavailable. Export a backup and free space.');return false}}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
function fmtTime(s){s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function fmtDate(s){return new Date(s).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}
function questions(){return db.questions}
function qBy(id){return db.questions.find(q=>q.id===id)}
function score(a){const correct=a.responses.filter(r=>r.selected===qBy(r.qid)?.answer).filter(r=>r.selected!==null&&r.selected!==undefined).length;const wrong=a.responses.filter(r=>r.selected!==null&&r.selected!==undefined&&r.selected!==qBy(r.qid)?.answer).length;const skipped=a.responses.length-correct-wrong;const cfg=a.config||db.config;return {correct,wrong,skipped,score:correct*cfg.marksCorrect-wrong*cfg.negativeMarks,accuracy:correct+wrong?correct/(correct+wrong)*100:0,attemptRate:a.responses.length?((correct+wrong)/a.responses.length)*100:0,loss:wrong*cfg.negativeMarks}}
function init(){load();fetch('./data/questions.json').then(r=>r.json()).then(qs=>{if(!db.questions.length){db.questions=qs;save()}else{const ids=new Set(db.questions.map(q=>q.id));qs.forEach(q=>{if(!ids.has(q.id))db.questions.push(q)});save()}render()}).catch(()=>{if(!db.questions.length)db.questions=[];render();toast('Offline: showing locally saved questions')});renderNav();$('#theme-btn').onclick=()=>{db.settings.theme=db.settings.theme==='dark'?'light':'dark';save();applyTheme()};$('#menu-btn').onclick=()=>{const side=$('.sidebar');side.style.display=side.style.display==='flex'?'none':'flex';side.style.position='fixed';side.style.width='245px'};window.addEventListener('beforeunload',()=>{if(db.active){db.active.interrupted=true;db.active.lastSaved=Date.now();save()}});document.addEventListener('keydown',onKeys);if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}
function renderNav(){const make=cls=>nav.map(([id,ico,label])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}"><span class="nav-icon">${ico}</span><span>${label}</span></button>`).join('');$('#side-nav').innerHTML=make('side');$('#bottom-nav').innerHTML=nav.filter(x=>['home','practice','mock','revision','analytics'].includes(x[0])).map(([id,ico,label])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}"><span class="nav-icon">${ico}</span><span>${label}</span></button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page))}
function go(p){if(db.active&&p!=='exam'&&p!=='results'){if(!confirm('A test is in progress. Leave the test screen? Your answers will be saved and you can resume it.'))return;db.active.interrupted=true;clearInterval(timer);save()}page=p;db.lastPage=p;save();renderNav();render();window.scrollTo(0,0)}
function applyTheme(){document.body.classList.toggle('dark',db.settings.theme==='dark')}
function render(){applyTheme();const titles={home:'Overview',practice:'Practice centre',papers:'PYQ papers',mock:'Mock tests',revision:'Revision studio',analytics:'Performance analytics',planner:'Study planner',bank:'Question bank',settings:'Settings',exam:'Test in progress',results:'Test scorecard'};$('#page-title').textContent=titles[page]||'PET Master';const views={home:homeView,practice:practiceView,papers:papersView,mock:mockView,revision:revisionView,analytics:analyticsView,planner:plannerView,bank:bankView,settings:settingsView,exam:examView,results:resultsView};$('#view').innerHTML=(views[page]||homeView)();bind();}
function metric(label,value,icon,note=''){return `<div class="card"><div class="metric-row"><span class="metric-label">${label}</span><span class="metric-icon">${icon}</span></div><div class="metric">${value}</div><div class="stat-note">${note}</div></div>`}
function allStats(){const done=db.attempts.filter(a=>a.status==='submitted');const sums=done.map(score);const resp=done.flatMap(a=>a.responses);const right=resp.filter(r=>r.selected!==null&&qBy(r.qid)&&r.selected===qBy(r.qid).answer).length;const attempted=resp.filter(r=>r.selected!==null&&r.selected!==undefined).length;return {done,sums,resp,right,attempted,accuracy:attempted?right/attempted*100:0,study:done.reduce((n,a)=>n+(a.elapsed||0),0)}}
function topicStats(){const map={};db.attempts.filter(a=>a.status==='submitted').forEach(a=>a.responses.forEach(r=>{const q=qBy(r.qid);if(!q)return;let x=map[q.topic]||(map[q.topic]={topic:q.topic,subject:q.subject,correct:0,wrong:0,seen:0,seconds:0});x.seen++;x.seconds+=r.seconds||0;if(r.selected===null||r.selected===undefined)return;if(r.selected===q.answer)x.correct++;else x.wrong++}));return Object.values(map).map(x=>({...x,accuracy:x.correct+x.wrong?x.correct/(x.correct+x.wrong)*100:0})).sort((a,b)=>a.accuracy-b.accuracy)}
function homeView(){const st=allStats(),topics=topicStats(),weak=topics.filter(t=>t.correct+t.wrong>=2).slice(0,3),last=db.attempts.filter(a=>a.status==='submitted').at(-1);const due=Object.entries(db.revision).filter(([id,r])=>new Date(r.due)<=new Date()).length;const qCount=db.questions.length,verified=db.questions.filter(q=>['VERIFIED OFFICIAL PYQ','CROSS-VERIFIED PYQ'].includes(q.status)).length;return `<div class="hero"><div><div class="eyebrow">SMALL STEPS. REAL PROGRESS.</div><h2>Build your PET readiness,<br>one question at a time.</h2><p>Practice deliberately, review every mistake, and let your own results guide the next session. Your data is stored on this device.</p><div class="hero-actions"><button class="btn primary" data-action="start-mock">▶ Start a mock</button><button class="btn light" data-action="start-practice">Practice questions ↗</button></div></div><div class="pill">${st.done.length} completed tests</div></div><div class="grid grid-4">${metric('Questions attempted',st.attempted,'◎',`${qCount} questions in your local bank`)}${metric('Overall accuracy',`${st.accuracy.toFixed(1)}%`,'↗','Correct ÷ answered questions')}${metric('Study time',`${Math.floor(st.study/3600)}h ${Math.floor(st.study%3600/60)}m`,'◷','Across submitted tests')}${metric('Revision due',due,'↻','Questions scheduled for review')}</div><div class="grid grid-2" style="margin-top:18px"><div class="card"><div class="card-head"><h2>Subject progress</h2><span class="pill">From your attempts</span></div>${subjectProgress()}</div><div class="card"><div class="card-head"><h2>Focus next</h2><span class="pill amber">Adaptive</span></div>${weak.length?weak.map(t=>`<div class="list-row"><div><b>${esc(t.topic)}</b><p>${esc(t.subject)} · ${t.correct+t.wrong} answered · ${t.accuracy.toFixed(0)}% accuracy</p></div><button class="btn outline" data-topic="${esc(t.topic)}">Drill</button></div>`).join(''):`<div class="empty"><strong>Your weak-area map will appear here</strong>Complete practice sessions so recommendations can be based on your actual answers.</div>`}</div></div><div class="grid grid-2" style="margin-top:18px"><div class="card"><div class="card-head"><h2>Pick up where you left off</h2></div>${db.active?`<div class="list-row"><div><b>Unfinished ${esc(db.active.mode)} session</b><p>${db.active.responses.filter(r=>r.selected!=null).length} answers saved · ${db.active.interrupted?'Interrupted session':'In progress'}</p></div><button class="btn" data-action="resume">Resume</button></div>`:last?`<div class="list-row"><div><b>Last session · ${fmtDate(last.endedAt)}</b><p>${score(last).score.toFixed(2)} marks · ${score(last).accuracy.toFixed(0)}% accuracy</p></div><button class="btn outline" data-attempt="${last.id}">Review</button></div>`:`<div class="empty"><strong>No test history yet</strong>Take a short practice session to begin your personal analytics.</div>`}<div class="list-row"><div><b>Review notebook</b><p>${Object.keys(db.mistakes).length} questions saved for targeted review</p></div><button class="btn outline" data-page="revision">Open</button></div></div><div class="card"><div class="card-head"><h2>Bank coverage</h2><span class="pill">Live count</span></div><div class="grid grid-2"><div><div class="metric">${qCount}</div><div class="metric-label">Total questions</div></div><div><div class="metric">${verified}</div><div class="metric-label">Confirmed PYQs</div></div></div><div class="progress"><span style="width:${qCount?verified/qCount*100:0}%"></span></div><p class="tagline">Starter content currently consists of original practice questions. No question is presented as a verified PYQ without source evidence.</p><button class="btn outline" data-page="bank">Manage question bank</button></div></div>`}
function subjectProgress(){const subs=[...new Set(db.questions.map(q=>q.subject))];if(!allStats().resp.length)return `<div class="empty"><strong>No subject data yet</strong>Attempt questions to calculate your accuracy by subject.</div>`;return subs.map(s=>{const qs=db.questions.filter(q=>q.subject===s);let n=0,c=0;allStats().resp.forEach(r=>{if(qs.some(q=>q.id===r.qid)&&r.selected!=null){n++;if(r.selected===qBy(r.qid)?.answer)c++}});return `<div class="subject-row"><span>${esc(s)}</span><b>${n?Math.round(c/n*100)+'%':'—'}</b><div class="progress"><span style="width:${n?c/n*100:0}%"></span></div></div>`}).join('')}
function practiceView(){const subjects=[...new Set(db.questions.map(q=>q.subject))];return `<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Build a practice session</h2><span class="pill green">Feedback enabled</span></div><p class="tagline">Choose a subject, topic and session length. Correct answers and option-wise explanations appear after you answer.</p><div class="toolbar"><label class="field grow">Subject<select id="p-subject"><option value="">All subjects</option>${subjects.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label class="field grow">Topic<select id="p-topic"><option value="">All topics</option>${[...new Set(db.questions.map(q=>q.topic))].map(s=>`<option>${esc(s)}</option>`).join('')}</select></label></div><div class="toolbar"><label class="field">Question count<select id="p-count">${[5,10,15,20,25,50,100].map(n=>`<option ${n===5?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Difficulty<select id="p-difficulty"><option value="">Any</option><option>Easy</option><option>Medium</option><option>Hard</option></select></label></div><label class="field">Mode<select id="p-mode"><option value="practice">Learn with explanations</option><option value="weak">Weak topics</option><option value="mistakes">Mistake notebook</option><option value="revision">Due revision</option><option value="daily">Daily challenge</option></select></label><div class="spacer"></div><button class="btn" data-action="build-practice">Start practice →</button></div><div class="card"><div class="card-head"><h2>How practice works</h2></div><div class="list-row"><div><b>Confidence check</b><p>Sure / unsure / guess (optional).</p></div><span>◉</span></div><div class="list-row"><div><b>Every option explained</b><p>Understand why each choice is right or wrong.</p></div><span>✎</span></div><div class="list-row"><div><b>Review scheduling</b><p>Wrong answers can be added to spaced revision.</p></div><span>↻</span></div><div class="list-row"><div><b>Authenticity label</b><p>Question source status is visible in every session.</p></div><span>✓</span></div></div></div><div class="section-title">Browse subjects</div><div class="grid grid-3">${subjects.map(s=>`<div class="card"><h3>${esc(s)}</h3><p class="tagline">${db.questions.filter(q=>q.subject===s).length} available questions</p><button class="btn outline" data-subject="${esc(s)}">Practice subject</button></div>`).join('')}</div>`}
function papersView(){const papers=[...new Set(db.questions.filter(q=>q.year).map(q=>`${q.year} · ${q.exam}`))];return `<div class="card"><div class="card-head"><h2>Previous-year paper library</h2><span class="pill amber">Source-sensitive</span></div><p class="tagline">Only questions marked VERIFIED OFFICIAL PYQ or CROSS-VERIFIED PYQ count as confirmed PYQs. The current starter bank does not include an authenticated paper set, so this list may be empty until you import sources.</p>${papers.length?papers.map(p=>`<div class="list-row"><b>${esc(p)}</b><button class="btn" data-paper="${esc(p)}">Attempt paper</button></div>`).join(''):`<div class="empty"><strong>No verified paper set imported yet</strong>Import a lawfully obtained paper's structured question data through Question Bank. Source URLs and shift metadata must be verified before using PYQ labels.</div>`}<button class="btn outline" data-page="bank">Open import manager</button></div><div class="card" style="margin-top:15px"><h2>Source-status guide</h2><div class="list-row"><span class="pill green">VERIFIED OFFICIAL PYQ</span><span class="small">Matched to official paper/scan</span></div><div class="list-row"><span class="pill green">CROSS-VERIFIED PYQ</span><span class="small">Matched to multiple credible copies</span></div><div class="list-row"><span class="pill amber">UNVERIFIED REPORTED PYQ</span><span class="small">Reported, not independently confirmed</span></div><div class="list-row"><span class="pill">ORIGINAL PRACTICE QUESTION</span><span class="small">Newly written learning material</span></div></div>`}
function mockView(){return `<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Full-length mock</h2><span class="pill">Exam mode</span></div><p class="tagline">Default configuration: 100 questions, 120 minutes, +1 correct, −0.25 incorrect. Check the official notification for your exam cycle before relying on these settings.</p><div class="grid grid-2"><label class="field">Question count<input id="m-count" type="number" min="1" max="500" value="${db.config.totalQuestions}"></label><label class="field">Duration (minutes)<input id="m-duration" type="number" min="1" max="300" value="${db.config.durationMinutes}"></label><label class="field">Marks per correct<input id="m-correct" type="number" min="0" step=".25" value="${db.config.marksCorrect}"></label><label class="field">Negative marks<input id="m-negative" type="number" min="0" step=".05" value="${db.config.negativeMarks}"></label></div><div class="spacer"></div><button class="btn" data-action="start-mock">Start timed mock →</button></div><div class="card"><div class="card-head"><h2>Test instructions</h2></div><div class="list-row"><div><b>Responses save automatically</b><p>Reload recovery is supported on this device.</p></div><span>✓</span></div><div class="list-row"><div><b>No answer reveal during timed mode</b><p>Full explanations unlock after submission.</p></div><span>◷</span></div><div class="list-row"><div><b>Negative marking applies</b><p>Unattempted answers score zero.</p></div><span>−</span></div><div class="list-row"><div><b>Question bank size</b><p>${db.questions.length} questions currently available.</p></div><span>▤</span></div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h2>Past attempts</h2></div>${db.attempts.filter(a=>a.status==='submitted').length?attemptRows():`<div class="empty"><strong>Your score history starts here</strong>Finish a test and its scorecard will be available here.</div>`}</div>`}
function attemptRows(){return db.attempts.filter(a=>a.status==='submitted').slice().reverse().map(a=>`<div class="list-row"><div><b>${esc(a.mode)} · ${fmtDate(a.endedAt)}</b><p>${score(a).correct} correct · ${score(a).wrong} incorrect · ${score(a).skipped} skipped</p></div><div><b>${score(a).score.toFixed(2)} marks</b><br><button class="btn outline" data-attempt="${a.id}">Review</button> <button class="btn outline" data-replay="${a.id}">Replay</button></div></div>`).join('')}
function begin(qs,mode,timed=false,cfg=null){if(!qs.length){toast('No matching questions. Import or choose another filter.');return}const old=db.active;if(old&&!old.status){if(!confirm('Replace the saved unfinished session? Its answers will be lost.'))return}const now=Date.now(),c=clone(cfg||db.config);db.active={id:'att-'+now+'-'+Math.random().toString(36).slice(2,7),mode,startedAt:now,lastSaved:now,elapsed:0,remaining:timed?c.durationMinutes*60:null,timed,config:c,status:'in-progress',interrupted:false,index:0,responses:qs.map(q=>({qid:q.id,selected:null,visited:false,review:false,confidence:null,seconds:0})),feedback:!timed};db.active.responses[0].visited=true;save();page='exam';renderNav();render();startTimer()}
function startTimer(){clearInterval(timer);if(!db.active?.timed)return;timer=setInterval(()=>{if(!db.active)return;db.active.remaining--;db.active.elapsed++;db.active.lastSaved=Date.now();if(db.active.remaining<=0){db.active.remaining=0;clearInterval(timer);submitTest(true);return}if(db.active.elapsed%5===0)save();const t=$('#timer');if(t)t.textContent=fmtTime(db.active.remaining)},1000)}
function activeQ(){return qBy(db.active?.responses[db.active.index]?.qid)}
function examView(){const a=db.active;if(!a)return `<div class="card empty"><strong>No active session</strong><button class="btn" data-page="mock">Set up a test</button></div>`;const r=a.responses[a.index],q=qBy(r.qid);if(!q)return `<div class="card">Question missing from bank. Restore your backup.</div>`;const timed=a.timed;return `<div class="exam-head"><div><div class="eyebrow">${esc(a.mode.toUpperCase())} · ${a.index+1} OF ${a.responses.length}</div><h2 style="font:800 18px Manrope;margin:6px 0">Question ${a.index+1}</h2><div class="small muted">${esc(q.subject)} · ${esc(q.topic)}</div></div><div>${timed?`<div class="timer" id="timer">${fmtTime(a.remaining)}</div>`:`<span class="pill green">Practice mode</span>`}<div class="small muted" style="text-align:right;margin-top:5px">${a.responses.filter(x=>x.selected!=null).length} answered</div></div></div><div class="grid grid-2" style="margin-top:16px;align-items:start"><div class="card question-card"><div class="card-head"><span class="pill">${esc(q.status)}</span><button class="btn outline" data-action="bookmark" data-qid="${q.id}">${db.bookmarks.includes(q.id)?'★ Saved':'☆ Bookmark'}</button></div><div class="question-text">${esc(q.text)}</div>${q.options.map((o,i)=>`<button class="option ${r.selected===i?'selected':''}" data-answer="${i}" ${timed?'':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(o)}</span></button>`).join('')}<div class="toolbar" style="margin-top:16px"><label class="field grow">Confidence (optional)<select id="confidence"><option value="">Not set</option><option value="Sure" ${r.confidence==='Sure'?'selected':''}>Sure</option><option value="Unsure" ${r.confidence==='Unsure'?'selected':''}>Unsure</option><option value="Guess" ${r.confidence==='Guess'?'selected':''}>Guess</option></select></label></div>${!timed&&a.feedback?practiceExplanation(q,r):''}<div class="toolbar" style="margin-top:17px"><button class="btn outline" data-action="prev" ${a.index===0?'disabled':''}>← Previous</button><button class="btn outline" data-action="clear">Clear</button><button class="btn outline" data-action="review">${r.review?'Unmark review':'Mark review'}</button><button class="btn" data-action="next">${a.index===a.responses.length-1?'Finish →':'Next →'}</button></div></div><div class="card"><div class="card-head"><h2>Question palette</h2><span class="pill">${a.responses.length} questions</span></div><div class="palette">${a.responses.map((x,i)=>`<button class="${i===a.index?'current ':''}${x.review?'review ':x.selected!=null?'answered ':x.visited?'visited ':''}" data-jump="${i}" aria-label="Question ${i+1}">${i+1}</button>`).join('')}</div><div class="spacer"></div><div class="small muted">🟩 Answered · 🟨 Marked for review · ⬜ Not visited</div><div class="spacer"></div><div class="list-row"><span class="small">Answered</span><b>${a.responses.filter(x=>x.selected!=null).length}</b></div><div class="list-row"><span class="small">Marked for review</span><b>${a.responses.filter(x=>x.review).length}</b></div><div class="list-row"><span class="small">Unanswered</span><b>${a.responses.filter(x=>x.selected==null).length}</b></div><button class="btn danger" style="width:100%;margin-top:14px" data-action="submit">Submit test</button></div></div>`}
function practiceExplanation(q,r){const answered=r.selected!=null;return `<div class="explanation"><b>${!answered?'Choose an answer to reveal the explanation':r.selected===q.answer?'Correct — nice work!':'Not quite — review the concept'}</b>${answered?`<p>${esc(q.explanation)}</p><div>${q.options.map((o,i)=>`<div class="option-explain"><b>${'ABCD'[i]} · ${i===q.answer?'Correct answer':'Option '+ 'ABCD'[i]}</b> — ${esc(q.optionExplanations?.[i]||'No separate explanation provided.')}</div>`).join('')}</div><p><b>Remember:</b> ${esc(q.keyFact||'Review the core concept.')}</p><p><b>Exam tip:</b> ${esc(q.tip||'Read the question carefully.')}</p><p class="small">${esc(q.status)} · ${esc(q.sourceName||'Source not supplied')} ${q.sourceUrl?`· <a href="${esc(q.sourceUrl)}" target="_blank" rel="noreferrer">Source</a>`:''}</p><div class="toolbar"><button class="btn outline" data-action="note" data-qid="${q.id}">Add note</button><button class="btn outline" data-action="schedule" data-qid="${q.id}">Add to revision</button><button class="btn outline" data-action="report" data-qid="${q.id}">Report issue</button><button class="btn outline" data-action="mistake" data-qid="${q.id}">Classify mistake</button></div>`:''}</div>`}
function submitTest(auto=false){const a=db.active;if(!a)return;clearInterval(timer);a.status='submitted';a.endedAt=Date.now();a.elapsed=a.timed?(a.config.durationMinutes*60-a.remaining):a.responses.reduce((n,r)=>n+(r.seconds||0),0);a.autoSubmitted=auto;const st=score(a);db.attempts.push(clone(a));db.active=null;save();page='results';renderNav();render();toast(auto?'Time expired. Test submitted automatically.':'Test submitted. Score saved.');}
function resultsView(){const a=db.attempts.at(-1);if(!a)return `<div class="card empty">No completed test found.</div>`;const s=score(a);const max=a.responses.length*(a.config.marksCorrect||1);const avg=a.responses.length?a.elapsed/a.responses.length:0;return `<div class="hero"><div><div class="eyebrow">SESSION COMPLETE</div><h2>${s.score.toFixed(2)} <span style="font-size:14px">/ ${max}</span></h2><p>${s.correct} correct · ${s.wrong} incorrect · ${s.skipped} unattempted. Score uses the configuration saved with this attempt.</p><div class="hero-actions"><button class="btn primary" data-action="review-results">Review explanations</button><button class="btn light" data-action="export-score">Export CSV</button></div></div><span class="pill">${esc(a.mode)}</span></div><div class="grid grid-4">${metric('Raw correct',s.correct,'✓','Count, before marking adjustments')}${metric('Accuracy',`${s.accuracy.toFixed(1)}%`,'↗','Correct ÷ attempted; skipped excluded')}${metric('Attempt rate',`${s.attemptRate.toFixed(1)}%`,'◉','Attempted ÷ all questions')}${metric('Negative-mark loss',s.loss.toFixed(2),'−','Marks deducted for wrong answers')}</div><div class="grid grid-2" style="margin-top:17px"><div class="card"><h2>Response summary</h2><div class="list-row"><span>Net marks</span><b>${s.score.toFixed(2)}</b></div><div class="list-row"><span>Marks percentage</span><b>${max?Math.max(0,s.score/max*100).toFixed(1):0}%</b></div><div class="list-row"><span>Time taken</span><b>${fmtTime(a.elapsed)}</b></div><div class="list-row"><span>Average time per question</span><b>${avg.toFixed(1)} sec</b></div><p class="tagline">Accuracy and marks percentage are different: accuracy excludes skipped questions; marks percentage includes the configured penalty and total possible marks.</p></div><div class="card"><h2>Subject performance</h2>${resultSubjects(a)}</div></div><div class="card" style="margin-top:17px"><div class="card-head"><h2>Question-by-question review</h2><span class="pill">Option-wise explanations</span></div>${a.responses.map((r,i)=>{const q=qBy(r.qid);if(!q)return '';const good=r.selected===q.answer;return `<details class="list-row" style="display:block"><summary><b>Q${i+1}. ${esc(q.text)}</b><span class="pill ${r.selected==null?'amber':good?'green':'red'}" style="margin-left:8px">${r.selected==null?'Skipped':good?'Correct':'Incorrect'}</span><p>${esc(q.subject)} · Your answer: ${r.selected==null?'Not attempted':'ABCD'[r.selected]} · Correct: ${'ABCD'[q.answer]}</p></summary>${practiceExplanation(q,r)}</details>`}).join('')}</div>`}
function resultSubjects(a){const m={};a.responses.forEach(r=>{const q=qBy(r.qid);if(!q)return;let x=m[q.subject]||(m[q.subject]={n:0,c:0,w:0});x.n++;if(r.selected!=null){if(r.selected===q.answer)x.c++;else x.w++}});return Object.entries(m).map(([k,v])=>`<div class="subject-row"><span>${esc(k)}</span><b>${v.c+v.w?Math.round(v.c/(v.c+v.w)*100)+'%':'—'}</b><div class="progress"><span style="width:${v.c+v.w?v.c/(v.c+v.w)*100:0}%"></span></div><div class="small muted">${v.c} correct · ${v.w} incorrect · ${v.n-v.c-v.w} skipped</div></div>`).join('')}
function revisionView(){const due=Object.entries(db.revision).filter(([id,r])=>new Date(r.due)<=new Date());const mistakes=Object.keys(db.mistakes);return `<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Due for revision</h2><span class="pill amber">${due.length} due</span></div>${due.length?due.map(([id,r])=>{const q=qBy(id);return q?`<div class="list-row"><div><b>${esc(q.text)}</b><p>${esc(q.topic)} · due ${fmtDate(r.due)}</p></div><button class="btn outline" data-revise="${id}">Review</button></div>`:''}).join(''):`<div class="empty"><strong>You're all caught up</strong>Wrong answers can be scheduled from practice or a scorecard.</div>`}</div><div class="card"><div class="card-head"><h2>Mistake notebook</h2><span class="pill red">${mistakes.length} saved</span></div>${mistakes.length?mistakes.map(id=>{const q=qBy(id);return q?`<div class="list-row"><div><b>${esc(q.text)}</b><p>${esc(db.mistakes[id].type||'Needs classification')} · ${esc(q.topic)}</p></div><button class="btn outline" data-revise="${id}">Retake</button></div>`:''}).join(''):`<div class="empty"><strong>No mistakes recorded yet</strong>Incorrect practice answers are added automatically after an answer is selected.</div>`}<button class="btn" data-action="practice-mistakes">Retake mistakes</button></div></div><div class="card" style="margin-top:16px"><h2>Spaced repetition guide</h2><p class="tagline">Default review ladder: same day → 1 day → 3 days → 7 days → 14 days → 30 days. Correct recall moves forward; a forgotten answer returns to an earlier interval. These are configurable study aids, not a guarantee of optimal learning.</p></div>`}
function analyticsView(){const done=db.attempts.filter(a=>a.status==='submitted');if(!done.length)return `<div class="card empty"><strong>Analytics need real attempts</strong>Complete a mock or practice session. Charts will then reflect your recorded results—no sample data is fabricated.<div class="spacer"></div><button class="btn" data-page="practice">Start practice</button></div>`;const rows=done.slice(-10).map(a=>({a,s:score(a)}));const max=Math.max(1,...rows.map(x=>x.s.score));const topics=topicStats();return `<div class="grid grid-4">${metric('Completed sessions',done.length,'▤','Submitted tests only')}${metric('Best score',Math.max(...done.map(a=>score(a).score)).toFixed(2),'★','Among recorded attempts')}${metric('Average accuracy',`${(done.reduce((n,a)=>n+score(a).accuracy,0)/done.length).toFixed(1)}%`,'↗','Mean session accuracy')}${metric('Mistake rate',`${(done.reduce((n,a)=>n+score(a).wrong,0)/Math.max(1,done.reduce((n,a)=>n+a.responses.length,0))*100).toFixed(1)}%`,'−','Wrong answers ÷ all responses')}</div><div class="grid grid-2" style="margin-top:17px"><div class="card"><h2>Score over time</h2><div class="chart">${lineChart(rows.map(x=>x.s.score),max)}</div><p class="stat-note">Each point is one submitted attempt, in chronological order. Scores use each attempt's saved marking configuration.</p></div><div class="card"><h2>Topic accuracy</h2>${topics.length?topics.slice(0,8).map(t=>`<div class="bar-row"><span title="${esc(t.topic)}">${esc(t.topic.slice(0,18))}</span><div class="bar-track"><span style="width:${t.accuracy}%"></span></div><b>${t.accuracy.toFixed(0)}%</b></div>`).join(''):`<div class="empty">No topic data yet.</div>`}<p class="stat-note">Topics with fewer than two answers are not treated as weak/mastered. Use small samples cautiously.</p></div></div><div class="grid grid-2" style="margin-top:17px"><div class="card"><h2>Confidence calibration</h2>${confidenceStats()}</div><div class="card"><h2>Repeat intelligence</h2><p class="tagline">Current bank coverage: ${db.questions.filter(q=>['VERIFIED OFFICIAL PYQ','CROSS-VERIFIED PYQ'].includes(q.status)).length} confirmed PYQs across ${new Set(db.questions.filter(q=>q.year&&['VERIFIED OFFICIAL PYQ','CROSS-VERIFIED PYQ'].includes(q.status)).map(q=>q.year)).size} verified years.</p><p class="tagline">Concept frequency is not reported until verified source papers are present. Original practice questions do not count as PYQ occurrences.</p></div></div><div class="card" style="margin-top:17px"><div class="card-head"><h2>Attempt history</h2><button class="btn outline" data-action="export-all-attempts">Export CSV</button></div>${attemptRows()}</div>`}
function lineChart(vals,max){const w=520,h=180,p=18;if(vals.length===1)vals.push(vals[0]);const pts=vals.map((v,i)=>`${p+i*(w-2*p)/Math.max(1,vals.length-1)},${h-p-v/max*(h-2*p)}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Score trend chart" style="width:100%;height:100%"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" stroke="var(--line)"/><polyline points="${pts}" fill="none" stroke="#3c94a4" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${vals.map((v,i)=>`<circle cx="${p+i*(w-2*p)/Math.max(1,vals.length-1)}" cy="${h-p-v/max*(h-2*p)}" r="4" fill="#3c94a4"/>`).join('')}</svg>`}
function confidenceStats(){const rows=db.attempts.filter(a=>a.status==='submitted').flatMap(a=>a.responses).filter(r=>r.confidence);if(!rows.length)return `<div class="empty"><strong>No confidence data yet</strong>Use Sure / Unsure / Guess in practice mode. This tracker only uses confidence you explicitly select.</div>`;return ['Sure','Unsure','Guess'].map(c=>{const rr=rows.filter(r=>r.confidence===c),correct=rr.filter(r=>qBy(r.qid)&&r.selected===qBy(r.qid).answer).length;return `<div class="list-row"><div><b>${c}</b><p>${rr.length} answers recorded</p></div><b>${rr.length?(correct/rr.length*100).toFixed(0):0}% correct</b></div>`}).join('')}
function plannerView(){const tasks=db.planner;return `<div class="grid grid-2"><div class="card"><h2>Build today's plan</h2><p class="tagline">Set a realistic time budget; suggestions use your weak topics and revision queue when available.</p><div class="toolbar"><label class="field grow">Available time (minutes)<select id="plan-min"><option>30</option><option selected>60</option><option>120</option></select></label><label class="field grow">Target test date<input type="date" id="plan-date"></label></div><button class="btn" data-action="generate-plan">Generate plan</button><div class="spacer"></div><div class="grid grid-3"><button class="btn outline" data-plan-template="30">30 min</button><button class="btn outline" data-plan-template="60">60 min</button><button class="btn outline" data-plan-template="120">120 min</button></div></div><div class="card"><h2>Study planner</h2>${tasks.length?tasks.map((t,i)=>`<div class="list-row"><label style="display:flex;gap:10px;align-items:center"><input type="checkbox" data-task-done="${i}" ${t.done?'checked':''}><span><b>${esc(t.title)}</b><p>${t.minutes} min · ${esc(t.reason||'Planned session')}</p></span></label><button class="btn outline" data-task-delete="${i}">×</button></div>`).join(''):`<div class="empty"><strong>No plan yet</strong>Generate a plan that fits your available study time.</div>`}</div></div><div class="card" style="margin-top:16px"><h2>Planning principles</h2><p class="tagline">Recommendations are rules-based and not a promise of exam performance. Leave buffer time, prioritize overdue revisions, and use mock-test results to adjust the next plan.</p></div>`}
function bankView(){const query=(bankFilters.query||'').toLowerCase();const filtered=db.questions.filter(q=>(!query||[q.text,q.topic,q.subject,...(q.tags||[])].join(' ').toLowerCase().includes(query))&&(!bankFilters.subject||q.subject===bankFilters.subject)&&(!bankFilters.status||q.status===bankFilters.status));const statuses=['VERIFIED OFFICIAL PYQ','CROSS-VERIFIED PYQ','UNVERIFIED REPORTED PYQ','ORIGINAL PRACTICE QUESTION','EXPECTED QUESTION'];return `<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Question bank manager</h2><span class="pill">${filtered.length} shown / ${db.questions.length}</span></div><div class="toolbar"><input class="search" id="bank-search" placeholder="Search questions, topics, tags…" value="${esc(bankFilters.query||'')}"><select id="bank-subject"><option value="">All subjects</option>${[...new Set(db.questions.map(q=>q.subject))].map(s=>`<option ${bankFilters.subject===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="bank-status"><option value="">All statuses</option>${statuses.map(s=>`<option ${bankFilters.status===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Question / topic</th><th>Source status</th><th>Subject</th><th></th></tr></thead><tbody>${filtered.map(q=>`<tr><td><b>${esc(q.text.slice(0,65))}${q.text.length>65?'…':''}</b><br><span class="muted">${esc(q.topic)} · ${esc(q.id)}</span></td><td><span class="pill ${q.status.includes('VERIFIED')?'green':q.status.includes('UNVERIFIED')?'amber':''}">${esc(q.status)}</span></td><td>${esc(q.subject)}</td><td><button class="btn outline" data-edit-q="${q.id}">Edit</button></td></tr>`).join('')}</tbody></table></div><div class="spacer"></div><div class="toolbar"><button class="btn" data-action="new-question">+ Add question</button><button class="btn outline" data-action="import-json">Import JSON</button><button class="btn outline" data-action="import-csv">Import CSV</button><button class="btn outline" data-action="export-bank">Export JSON</button><button class="btn outline" data-action="export-csv">Export CSV</button></div><p class="stat-note">Imports are validated and duplicate IDs are skipped. Confirmed PYQ labels require a source reference and human verification; importing does not itself verify authenticity.</p></div><div class="card"><h2>Coverage report</h2><div class="grid grid-2"><div><div class="metric">${db.questions.length}</div><div class="metric-label">Total questions</div></div><div><div class="metric">${db.questions.filter(q=>q.status==='ORIGINAL PRACTICE QUESTION').length}</div><div class="metric-label">Original practice</div></div><div><div class="metric">${db.questions.filter(q=>['VERIFIED OFFICIAL PYQ','CROSS-VERIFIED PYQ'].includes(q.status)).length}</div><div class="metric-label">Confirmed PYQs</div></div><div><div class="metric">${db.questions.filter(q=>q.status==='UNVERIFIED REPORTED PYQ').length}</div><div class="metric-label">Unverified reports</div></div></div><div class="spacer"></div>${[...new Set(db.questions.map(q=>q.subject))].map(s=>`<div class="subject-row"><span>${esc(s)}</span><b>${db.questions.filter(q=>q.subject===s).length}</b><div class="progress"><span style="width:${db.questions.filter(q=>q.subject===s).length/Math.max(1,db.questions.length)*100}%"></span></div></div>`).join('')}<p class="tagline">Years and shifts represented: ${new Set(db.questions.filter(q=>q.year).map(q=>q.year)).size} years. Coverage is limited to data imported into this device.</p></div></div>`}
function settingsView(){return `<div class="grid grid-2"><div class="card"><h2>Exam configuration</h2><p class="tagline">Default values are provisional. Check the relevant official UPSSSC PET notification before an actual exam simulation.</p><div class="grid grid-2"><label class="field">Questions<input id="cfg-count" type="number" min="1" max="500" value="${db.config.totalQuestions}"></label><label class="field">Duration (minutes)<input id="cfg-duration" type="number" min="1" max="300" value="${db.config.durationMinutes}"></label><label class="field">Correct marks<input id="cfg-correct" type="number" min="0" step=".25" value="${db.config.marksCorrect}"></label><label class="field">Negative marks<input id="cfg-negative" type="number" min="0" step=".05" value="${db.config.negativeMarks}"></label></div><div class="spacer"></div><button class="btn" data-action="save-config">Save configuration</button></div><div class="card"><h2>Privacy & backups</h2><p class="tagline">Attempts, notes, bookmarks, revision schedules and settings are saved in this browser's local storage. They do not automatically sync to another device. Clearing browser data can erase them.</p><div class="toolbar"><button class="btn" data-action="backup">Export full backup</button><button class="btn outline" data-action="restore">Restore backup</button></div><div class="toolbar"><button class="btn outline" data-action="export-personal">Export revision data</button><button class="btn danger" data-action="reset-history">Reset test history</button></div><button class="btn danger" data-action="delete-all">Delete all local study data</button></div><div class="card"><h2>Display preferences</h2><label class="field">Explanation language<select id="language"><option value="hinglish" ${db.settings.language==='hinglish'?'selected':''}>Hinglish</option><option value="hi" ${db.settings.language==='hi'?'selected':''}>Hindi</option><option value="en" ${db.settings.language==='en'?'selected':''}>English</option></select></label><div class="spacer"></div><button class="btn outline" data-action="toggle-theme">Toggle light / dark theme</button></div><div class="card"><h2>About this build</h2><p class="tagline">UPSSSC PET PYQ Master · Local-first static app · schema v${db.schemaVersion}. Core exam, score and revision features need no account, paid API or backend. The starter questions are explicitly labelled original practice material.</p><p class="tagline">Known limitations: no OCR pipeline, no cloud sync, and no authentic full PYQ paper included. Browser storage is device/browser-specific. Google Fonts is optional styling; core app files are cached for offline use after first successful load.</p></div></div>`}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b));document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const a=db.active,r=a.responses[a.index];r.selected=Number(b.dataset.answer);r.visited=true;r.seconds=(r.seconds||0)+1;a.lastSaved=Date.now();if(!a.timed){a.feedback=true;const q=qBy(r.qid);if(r.selected!==q.answer){db.mistakes[q.id]=db.mistakes[q.id]||{type:'Needs classification',createdAt:Date.now()};schedule(q.id,false)}else if(db.revision[q.id])schedule(q.id,true)}save();render()});document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{db.active.index=Number(b.dataset.jump);db.active.responses[db.active.index].visited=true;save();render()});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>begin(db.questions.filter(q=>q.topic===b.dataset.topic),'Weak-topic practice',false));document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>begin(db.questions.filter(q=>q.subject===b.dataset.subject),'Subject practice',false));document.querySelectorAll('[data-attempt]').forEach(b=>b.onclick=()=>{const a=db.attempts.find(x=>x.id===b.dataset.attempt);if(a){db.reviewing=a.id;page='results';renderNav();renderReviewAttempt(a)}});document.querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>{const a=db.attempts.find(x=>x.id===b.dataset.replay);if(a)begin(a.responses.map(r=>qBy(r.qid)).filter(Boolean),`Replay of ${a.mode}`,false,a.config)});document.querySelectorAll('[data-revise]').forEach(b=>b.onclick=()=>begin([qBy(b.dataset.revise)].filter(Boolean),'Revision',false));const confidence=$('#confidence');if(confidence)confidence.onchange=()=>{db.active.responses[db.active.index].confidence=confidence.value||null;save()};const bs=$('#bank-search');if(bs)bs.oninput=()=>{bankFilters.query=bs.value;const pos=bs.selectionStart;render();const n=$('#bank-search');n.focus();n.setSelectionRange(pos,pos)};['bank-subject','bank-status'].forEach(id=>{const e=$('#'+id);if(e)e.onchange=()=>{bankFilters[id==='bank-subject'?'subject':'status']=e.value;render()}});document.querySelectorAll('[data-edit-q]').forEach(b=>b.onclick=()=>questionForm(qBy(b.dataset.editQ)));document.querySelectorAll('[data-task-done]').forEach(b=>b.onchange=()=>{db.planner[Number(b.dataset.taskDone)].done=b.checked;save()});document.querySelectorAll('[data-task-delete]').forEach(b=>b.onclick=()=>{db.planner.splice(Number(b.dataset.taskDelete),1);save();render()});document.querySelectorAll('[data-plan-template]').forEach(b=>b.onclick=()=>generatePlan(Number(b.dataset.planTemplate)));const lang=$('#language');if(lang)lang.onchange=()=>{db.settings.language=lang.value;save();toast('Preference saved')};}
function action(act,b){const a=db.active;switch(act){case'start-mock':{const count=Math.max(1,Math.min(500,Number($('#m-count')?.value||db.config.totalQuestions))),duration=Math.max(1,Number($('#m-duration')?.value||db.config.durationMinutes)),correct=Math.max(0,Number($('#m-correct')?.value??db.config.marksCorrect)),negative=Math.max(0,Number($('#m-negative')?.value??db.config.negativeMarks));const cfg={totalQuestions:count,durationMinutes:duration,marksCorrect:correct,negativeMarks:negative,marksUnattempted:0};begin(shuffle(db.questions).slice(0,count),'Full mock',true,cfg);break}case'start-practice':go('practice');break;case'resume':page='exam';renderNav();render();startTimer();break;case'build-practice':{const s=$('#p-subject')?.value,t=$('#p-topic')?.value,d=$('#p-difficulty')?.value,n=Number($('#p-count')?.value||5),mode=$('#p-mode')?.value;let qs=db.questions.filter(q=>(!s||q.subject===s)&&(!t||q.topic===t)&&(!d||q.difficulty===d));if(mode==='weak'){const weak=topicStats().filter(x=>x.accuracy<65&&x.correct+x.wrong>=2).map(x=>x.topic);qs=qs.filter(q=>weak.includes(q.topic))}if(mode==='mistakes')qs=qs.filter(q=>db.mistakes[q.id]);if(mode==='revision')qs=qs.filter(q=>db.revision[q.id]&&new Date(db.revision[q.id].due)<=new Date());if(mode==='daily')qs=shuffle(qs).slice(0,Math.min(n,5));begin(shuffle(qs).slice(0,n),mode==='daily'?'Daily challenge':mode==='weak'?'Weak-area practice':mode==='mistakes'?'Mistake notebook':mode==='revision'?'Due revision':'Practice',false);break}case'prev':if(a&&a.index>0){a.index--;a.responses[a.index].visited=true;save();render()}break;case'next':if(a&&a.index<a.responses.length-1){a.index++;a.responses[a.index].visited=true;save();render()}else if(a)confirmSubmit();break;case'clear':if(a){a.responses[a.index].selected=null;save();render()}break;case'review':if(a){a.responses[a.index].review=!a.responses[a.index].review;save();render()}break;case'submit':confirmSubmit();break;case'bookmark':toggleBookmark(b.dataset.qid);break;case'note':noteForm(b.dataset.qid);break;case'schedule':schedule(b.dataset.qid,false);save();toast('Added to revision');break;case'report':reportForm(b.dataset.qid);break;case'mistake':mistakeForm(b.dataset.qid);break;case'practice-mistakes':begin(Object.keys(db.mistakes).map(qBy).filter(Boolean),'Mistake notebook',false);break;case'review-results':$('#view').scrollIntoView({behavior:'smooth'});break;case'export-score':exportCSV([['Question','Your answer','Correct answer','Status','Subject','Topic'],...db.attempts.at(-1).responses.map(r=>{const q=qBy(r.qid);return [q?.text,r.selected==null?'Skipped':'ABCD'[r.selected],q?'ABCD'[q.answer]:'',r.selected==null?'Skipped':r.selected===q?.answer?'Correct':'Incorrect',q?.subject,q?.topic]})],'pet-scorecard.csv');break;case'export-all-attempts':exportCSV([['Date','Mode','Score','Correct','Wrong','Skipped','Accuracy'],...db.attempts.filter(a=>a.status==='submitted').map(a=>[a.endedAt,a.mode,score(a).score,score(a).correct,score(a).wrong,score(a).skipped,score(a).accuracy])],'pet-attempt-history.csv');break;case'generate-plan':generatePlan(Number($('#plan-min')?.value||60));break;case'new-question':questionForm(null);break;case'import-json':importFile('json');break;case'import-csv':importFile('csv');break;case'export-bank':download(JSON.stringify(db.questions,null,2),'pet-question-bank.json','application/json');break;case'export-csv':exportCSV([['id','text','optionA','optionB','optionC','optionD','answer','explanation','optionExplanations','subject','topic','status','exam','year','sourceName','sourceUrl','difficulty','keyFact','tip'],...db.questions.map(q=>[q.id,q.text,...q.options,q.answer,q.explanation,JSON.stringify(q.optionExplanations),q.subject,q.topic,q.status,q.exam,q.year,q.sourceName,q.sourceUrl,q.difficulty,q.keyFact,q.tip])],'pet-question-bank.csv');break;case'save-config':db.config={totalQuestions:Math.max(1,Number($('#cfg-count').value)),durationMinutes:Math.max(1,Number($('#cfg-duration').value)),marksCorrect:Math.max(0,Number($('#cfg-correct').value)),negativeMarks:Math.max(0,Number($('#cfg-negative').value)),marksUnattempted:0};save();toast('Configuration saved');break;case'toggle-theme':db.settings.theme=db.settings.theme==='dark'?'light':'dark';save();render();break;case'backup':download(JSON.stringify(db,null,2),'pet-master-backup.json','application/json');break;case'restore':importFile('backup');break;case'export-personal':download(JSON.stringify({bookmarks:db.bookmarks,notes:db.notes,revision:db.revision,mistakes:db.mistakes,flashcards:db.flashcards,planner:db.planner},null,2),'pet-revision-data.json','application/json');break;case'reset-history':if(confirm('Reset all test attempts and the unfinished test? This cannot be undone unless you exported a backup.')){db.attempts=[];db.active=null;db.mistakes={};save();go('home')}break;case'delete-all':if(confirm('Delete ALL local study data including questions, notes, attempts and settings? Export a backup first if needed.')){localStorage.removeItem(STORE);location.reload()}break}}
function confirmSubmit(){const a=db.active;if(!a)return;const unanswered=a.responses.filter(r=>r.selected==null).length;if(confirm(`Submit this test? ${unanswered} question(s) are unanswered. You cannot edit answers after submission.`))submitTest(false)}
function onKeys(e){if(page!=='exam'||!db.active)return;if(e.key==='ArrowRight'&&!e.target.matches('input,textarea,select'))action('next');if(e.key==='ArrowLeft'&&!e.target.matches('input,textarea,select'))action('prev');if(['1','2','3','4'].includes(e.key)) {const btn=$(`[data-answer="${Number(e.key)-1}"]`);if(btn)btn.click()}if(e.key.toLowerCase()==='m'&&!e.target.matches('input,textarea,select'))action('review')}
function shuffle(arr){return arr.slice().sort(()=>Math.random()-.5)}
function toggleBookmark(id){if(db.bookmarks.includes(id))db.bookmarks=db.bookmarks.filter(x=>x!==id);else db.bookmarks.push(id);save();render()}
function schedule(id,correct){const ladd=[0,1,3,7,14,30],old=db.revision[id]||{stage:0};const stage=correct?Math.min(ladd.length-1,(old.stage||0)+1):0;const due=new Date();due.setDate(due.getDate()+ladd[stage]);db.revision[id]={stage,due:due.toISOString(),lastReviewed:new Date().toISOString(),lastResult:correct?'remembered':'forgotten'};save()}
function noteForm(id){const q=qBy(id);openModal(`<h2>Personal note</h2><p class="tagline">${esc(q?.text||'Question')}</p><label class="field">Your note<textarea id="modal-note">${esc(db.notes[id]||'')}</textarea></label><div class="modal-actions"><button class="btn outline" data-close>Cancel</button><button class="btn" id="save-note">Save note</button></div>`);$('#save-note').onclick=()=>{db.notes[id]=$('#modal-note').value;save();closeModal();toast('Note saved')};}
function mistakeForm(id){const types=['Concept not understood','Fact forgotten','Confused between similar Articles or dates','Calculation error','Misread question','Incorrect elimination','Time pressure','Guessing error'];openModal(`<h2>Classify this mistake</h2><label class="field">Mistake type<select id="mistake-type">${types.map(t=>`<option ${db.mistakes[id]?.type===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="modal-actions"><button class="btn outline" data-close>Cancel</button><button class="btn" id="save-mistake">Save classification</button></div>`);$('#save-mistake').onclick=()=>{db.mistakes[id]={...(db.mistakes[id]||{}),type:$('#mistake-type').value,updatedAt:Date.now()};save();closeModal();toast('Mistake classification saved')};}
function reportForm(id){openModal(`<h2>Report a question issue</h2><p class="tagline">This report is saved locally for your review; it is not sent to a server.</p><label class="field">Issue type<select id="report-type"><option>Possible incorrect answer key</option><option>Question wording issue</option><option>Explanation needs review</option><option>Source verification needed</option></select></label><label class="field">Details<textarea id="report-details" placeholder="What seems incorrect? Include a source if available."></textarea></label><div class="modal-actions"><button class="btn outline" data-close>Cancel</button><button class="btn" id="save-report">Save report</button></div>`);$('#save-report').onclick=()=>{db.reports=db.reports||[];db.reports.push({qid:id,type:$('#report-type').value,details:$('#report-details').value,createdAt:Date.now(),status:'Needs review'});save();closeModal();toast('Report saved locally')};}
function questionForm(q){q=q||{id:'USER-'+Date.now(),text:'',options:['','','',''],answer:0,explanation:'',optionExplanations:['','','',''],subject:'General Knowledge',topic:'',difficulty:'Easy',status:'ORIGINAL PRACTICE QUESTION',exam:'',year:null,sourceName:'',sourceUrl:'',keyFact:'',tip:'',tags:[]};openModal(`<h2>${q.text?'Edit':'Add'} question</h2><div style="display:grid;gap:10px;max-height:65vh;overflow:auto;padding:2px"><label class="field">Question ID<input id="q-id" value="${esc(q.id)}"></label><label class="field">Question text<textarea id="q-text">${esc(q.text)}</textarea></label>${q.options.map((o,i)=>`<label class="field">Option ${'ABCD'[i]}<input id="q-opt-${i}" value="${esc(o)}"></label>`).join('')}<label class="field">Correct option<select id="q-answer">${[0,1,2,3].map(i=>`<option value="${i}" ${q.answer===i?'selected':''}>${'ABCD'[i]}</option>`).join('')}</select></label><label class="field">Correct explanation<textarea id="q-expl">${esc(q.explanation)}</textarea></label>${[0,1,2,3].map(i=>`<label class="field">Option ${'ABCD'[i]} explanation<textarea id="q-exp-${i}">${esc(q.optionExplanations?.[i]||'')}</textarea></label>`).join('')}<label class="field">Subject<input id="q-subject" value="${esc(q.subject)}"></label><label class="field">Topic<input id="q-topic" value="${esc(q.topic)}"></label><label class="field">Difficulty<select id="q-diff">${['Easy','Medium','Hard'].map(x=>`<option ${q.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Source status<select id="q-status">${['VERIFIED OFFICIAL PYQ','CROSS-VERIFIED PYQ','UNVERIFIED REPORTED PYQ','ORIGINAL PRACTICE QUESTION','EXPECTED QUESTION'].map(x=>`<option ${q.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Exam / paper name<input id="q-exam" value="${esc(q.exam||'')}"></label><label class="field">Year<input id="q-year" type="number" value="${esc(q.year||'')}"></label><label class="field">Source name<input id="q-source" value="${esc(q.sourceName||'')}"></label><label class="field">Source URL<input id="q-url" value="${esc(q.sourceUrl||'')}"></label><label class="field">Key fact<input id="q-fact" value="${esc(q.keyFact||'')}"></label><label class="field">Exam tip<input id="q-tip" value="${esc(q.tip||'')}"></label></div><div class="modal-actions"><button class="btn outline" data-close>Cancel</button><button class="btn" id="save-question">Save question</button></div>`);$('#save-question').onclick=()=>{const n={id:$('#q-id').value.trim(),text:$('#q-text').value.trim(),options:[0,1,2,3].map(i=>$('#q-opt-'+i).value.trim()),answer:Number($('#q-answer').value),explanation:$('#q-expl').value.trim(),optionExplanations:[0,1,2,3].map(i=>$('#q-exp-'+i).value.trim()),subject:$('#q-subject').value.trim(),topic:$('#q-topic').value.trim(),difficulty:$('#q-diff').value,status:$('#q-status').value,exam:$('#q-exam').value.trim(),year:Number($('#q-year').value)||null,sourceName:$('#q-source').value.trim(),sourceUrl:$('#q-url').value.trim(),keyFact:$('#q-fact').value.trim(),tip:$('#q-tip').value.trim(),tags:q.tags||[]};const err=validateQuestion(n);if(err){toast(err);return}if(['VERIFIED OFFICIAL PYQ','CROSS-VERIFIED PYQ'].includes(n.status)&&(!n.sourceName||!n.sourceUrl||!n.year)){toast('Confirmed PYQ status requires source name, URL and year. Verify them manually.');return}const idx=db.questions.findIndex(x=>x.id===n.id);if(idx>=0)db.questions[idx]=n;else db.questions.push(n);save();closeModal();render();toast('Question saved')};}
function validateQuestion(q){if(!q.id||!q.text||!q.subject||!q.topic)return 'ID, question, subject and topic are required.';if(!Array.isArray(q.options)||q.options.length!==4||q.options.some(x=>!x))return 'Exactly four non-empty options are required.';if(!Number.isInteger(q.answer)||q.answer<0||q.answer>3)return 'Correct answer must be A–D.';if(!q.explanation)return 'Add an explanation for the correct answer.';if(!Array.isArray(q.optionExplanations)||q.optionExplanations.length!==4||q.optionExplanations.some(x=>!x))return 'Provide a separate explanation for every option.';return ''}
function importFile(kind){const input=document.createElement('input');input.type='file';input.accept=kind==='csv'?'.csv,text/csv':'.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{const text=await file.text();if(kind==='backup'){const x=JSON.parse(text);if(!x||!Array.isArray(x.questions)||!x.config)throw Error('Backup schema is not valid.');if(!confirm(`Restore backup containing ${x.questions.length} questions and ${x.attempts?.length||0} attempts? This replaces current local data.`))return;db={...db,...x,schemaVersion:1};save();renderNav();render();toast('Backup restored');return}let qs=kind==='json'?JSON.parse(text):parseCSV(text).map(csvRowToQuestion);if(!Array.isArray(qs))throw Error('Import must be a JSON array of questions.');let added=0,dupes=0,invalid=0;for(const q of qs){const e=validateQuestion(q);if(e){invalid++;continue}if(db.questions.some(x=>x.id===q.id)){dupes++;continue}db.questions.push(q);added++}save();render();toast(`Imported ${added}; duplicates ${dupes}; invalid ${invalid}`)}catch(e){toast('Import failed: '+e.message)}};input.click()}
function parseCSV(s){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'&&quoted&&s[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(field);if(row.some(x=>x!==''))rows.push(row);row=[];field=''}else field+=c}if(field||row.length){row.push(field);rows.push(row)}const headers=rows.shift()||[];return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])))}
function csvRowToQuestion(r){return {...r,options:[r.optionA,r.optionB,r.optionC,r.optionD],answer:Number(r.answer),optionExplanations:typeof r.optionExplanations==='string'?JSON.parse(r.optionExplanations||'[]'):r.optionExplanations,year:Number(r.year)||null,tags:[]}}
function exportCSV(rows,name){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');download(csv,name,'text/csv;charset=utf-8')}
function download(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function generatePlan(minutes){const due=Object.entries(db.revision).filter(([id,r])=>new Date(r.due)<=new Date()).length,weak=topicStats().find(t=>t.correct+t.wrong>=2&&t.accuracy<70);const parts=minutes===30?[['Revision quick review',10,'Review due cards'],['Weak-topic drill',15,weak?`Recent accuracy in ${weak.topic} is ${weak.accuracy.toFixed(0)}%`:'Build a baseline'],['Error log',5,'Record one lesson']]:minutes===120?[['Due revision',25,`${due} due question(s)`],['Weak-topic drill',30,weak?`${weak.topic}: recent accuracy ${weak.accuracy.toFixed(0)}%`:'Build a topic baseline'],['Timed sectional test',40,'Practice pace and accuracy'],['Review every mistake',25,'Convert errors into revision']]:[['Due revision',15,`${due} due question(s)`],['Weak-topic drill',20,weak?`${weak.topic}: recent accuracy ${weak.accuracy.toFixed(0)}%`:'Build a topic baseline'],['Practice set',15,'Use a focused question set'],['Review mistakes',10,'Read option-wise explanations']];db.planner=parts.map(([title,m,reason])=>({title,minutes:m,reason,done:false,createdAt:Date.now()}));save();render();toast(`${minutes}-minute plan generated`)}
function openModal(html){$('#modal-content').innerHTML=html;const d=$('#modal');d.showModal();d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal())}function closeModal(){const d=$('#modal');if(d.open)d.close()}
function renderReviewAttempt(a){$('#page-title').textContent='Attempt review';$('#view').innerHTML=`<div class="card"><div class="card-head"><h2>${esc(a.mode)} · ${fmtDate(a.endedAt)}</h2><button class="btn outline" id="back-results">Back</button></div><p class="tagline">This review uses the selected historical attempt, without changing its original answers.</p>${a.responses.map((r,i)=>{const q=qBy(r.qid);if(!q)return '';return `<details class="list-row" style="display:block"><summary><b>Q${i+1}. ${esc(q.text)}</b> · ${r.selected==null?'Skipped':r.selected===q.answer?'Correct':'Incorrect'}</summary><p>Your answer: ${r.selected==null?'Skipped':'ABCD'[r.selected]} · Correct: ${'ABCD'[q.answer]}</p>${practiceExplanation(q,r)}</details>`}).join('')}</div>`;$('#back-results').onclick=()=>go('mock')}
init();
